/*
 * This file was generated by the Gradle 'init' task.
 */

plugins { id("buildlogic.server-conventions") }

tasks.named<Jar>("jar") { enabled = false }

publishing {
  publications.named<MavenPublication>("maven") {
    artifacts.clear()
    pom.packaging = "pom"
  }
}

val pomFile = file("build/publications/maven/pom-default.xml")

tasks.named("generatePomFileForMavenPublication") {
  doLast {
    var pom = pomFile.readText()
    pom = Regex("(?s)<dependencyManagement>.*?</dependencyManagement>\\s*").replace(pom, "")
    pom = Regex("(?s)<dependencies>.*?</dependencies>\\s*").replace(pom, "")
    pom =
      pom.replace(
        "</project>",
        "  <distributionManagement>\n" +
          "    <relocation>\n" +
          "      <artifactId>camunda-process-test-spring</artifactId>\n" +
          "      <message>camunda-process-test-spring-boot-4 has been replaced by camunda-process-test-spring</message>\n" +
          "    </relocation>\n" +
          "  </distributionManagement>\n" +
          "</project>",
      )

    pomFile.writeText(pom)
  }
}

description = "Camunda Process Test Spring Boot 4"
